    input  [7:0] b,
    output [7:0] s,
    output       overflow
);

    // Internal signal for the 9-bit sum (includes carry out)
    wire [8:0] sum;

    // Perform the addition.  The extra MSB captures the carry out.
    assign sum = {1'b0, a} + {1'b0, b};

    // The 8-bit result is the lower 8 bits of the sum.
    assign s = sum[7:0];

    // Overflow detection for signed 2's complement addition:
    // Overflow occurs if the carry into the MSB differs from the carry out of the MSB.
