    input  clk,
    input  j,
    input  k,
    output Q
);

    // Internal signal to hold the previous state
    reg Q_reg;

    // Synchronous always block triggered on the positive clock edge
    always @(posedge clk) begin
        case ({j, k})
            2'b00: Q_reg <= Q_reg;      // Hold state (Qold)
            2'b01: Q_reg <= 1'b0;       // Reset
            2'b10: Q_reg <= 1'b1;       // Set
