module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Combinational logic for next_state
    // Derived by inspection from the state transition table with one-hot encoding:
    // A (0001) -> in=0: A (0001), in=1: B (0010)
    // B (0010) -> in=0: C (0100), in=1: B (0010)
    // C (0100) -> in=0: A (0001), in=1: D (1000)
    // D (1000) -> in=0: C (0100), in=1: B (0010)

    assign next_state = (state == 4'b0001) ? {in, 1'b0, 1'b0, 1'b1} :
                        (state == 4'b0010) ? {1'b0, in, 1'b1, 1'b0} :
                        (state == 4'b0100) ? {1'b1, 1'b0, 1'b0, in} :
                        (state == 4'b1000) ? {1'b0, in, 1'b1, 1'b0} :
                                               4'b0000;

    // Combinational logic for output (Moore machine: output depends only on state)
    // Output is 1 only when state is D (4'b1000), otherwise 0.
    assign out = (state == 4'b1000) ? 1'b1 : 1'b0;

endmodule

Prob088_ece241_2014_q5b.code:
module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot encoded state register
    // State A: 2'b01 (bit 1 set)
    // State B: 2'b10 (bit 0 set)
    reg [1:0] state;
    reg [1:0] next_state;

    // Output assignment (Mealy output function)
    // z = 1 when in state B, regardless of x
    // z = 0 when in state A, regardless of x
    assign z = state[0];  // state[0] is the B bit in one-hot encoding

    // Next-state logic (Mealy state transitions)
    always @(*) begin
        case (state)
            2'b01: // State A
                if (x)
                    next_state = 2'b10; // Go to B, z=1
                else
                    next_state = 2'b01; // Stay in A, z=0
            2'b10: // State B
                if (x)
                    next_state = 2'b10; // Stay in B, z=0
                else
                    next_state = 2'b10; // Stay in B, z=1
            default: next_state = 2'b01; // Fallback to A
        endcase
    end

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // Reset to state A
        else
            state <= next_state;
    end

endmodule

