module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    // Internal state register for the FSM
    reg [1:0] state;

    // Synchronous reset and state update
    always @(posedge clk) begin
        if (reset) begin
            // On reset: assert shift_ena for exactly 4 cycles, then 0 forever
            state <= 2'd0;
        end else begin
            // State machine to generate 4-cycle enable pulse
            case (state)
                2'd0: state <= 2'd1;  // Start pulse
                2'd1: state <= 2'd2;  // Cycle 1
                2'd2: state <= 2'd3;  // Cycle 2
                2'd3: state <= 2'd4;  // Cycle 3
                2'd4: state <= 2'd0;  // Cycle 4, then wrap to idle
                default: state <= 2'd0;
            endcase
        end
    end

    // Output logic: shift_ena is high during the 4 clock cycles
    // We use state < 4'b100 (i.e., states 0,1,2,3) to generate the pulse
    assign shift_ena = (state < 2'd4);

endmodule

