    reg [WIDTH-1:0] next_shift;
    reg [WIDTH-1:0] bit_count; // Counter for number of bits processed
    reg [WIDTH-1:0] next_bit_count;

    // Output assignment: Z is the MSB of the shift register after complement.
    // In 2's complement, the MSB represents the sign bit.
    // After processing all bits, the output is the complemented MSB.
    // For arbitrary length, we output the complement of the last shifted bit
    // (which becomes the MSB of the accumulated value).
    assign z = ~shift_reg[WIDTH-1];

    // State transition logic (positive edge triggered, async reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= 2'b00;   // IDLE
            shift_reg   <= {WIDTH{1'b0}};
            bit_count   <= {WIDTH{1'b0}};
        end else begin
            state       <= next_state;
            shift_reg   <= next_shift;
            bit_count   <= next_bit_count;
        end
    end

    // Next state and register update logic (Moore machine)
    always @(*) begin
        // Default assignments (hold state)
        next_state      = state;
        next_shift      = shift_reg;
        next_bit_count  = bit_count;

        case (state)
            2'b00: // IDLE
                begin
                    // Wait for reset release (areset de-asserted)
                    if (!areset) begin
                        // Start accepting bits
                        next_state = 2'b01;
                        next_bit_count = 1'b1; // First bit incoming
                        // Shift the first bit into LSB
                        next_shift = {shift_reg[WIDTH-2:0], x};
