            // If the current w is 1, increment the count (capped at 2).
            // If w is 0, the count stays as is (it will be evaluated at
            // the end of the three‑cycle window).
            if (w == 1'b1) begin
                case (ctx[3:2])
                    2'b00: ctx[3:2] <= 2'b01; // 0 -> 1
                    2'b01: ctx[3:2] <= 2'b10; // 1 -> 2
                    2'b10: ctx[3:2] <= 2'b10; // 2 stays 2 (capped)
                    default: ctx[3:2] <= 2'b00;
                endcase
            end
            // If w == 0 we do nothing to the count here; the count
            // already reflects the number of 1's seen so far.
        end
    end

    // Output logic: z should be 1 in the clock cycle *after* a window
    // in which w was 1 in exactly two of the three cycles.
    // We detect the completion of a three‑cycle window by checking
    // when the cycle index rolls over from 2 back to 0.
    // At that moment we evaluate whether count == 2 exactly.

    always_comb begin
        // Default z is 0
        z = 1'b0;

        // A window is complete when the cycle index is 00 and we are
        // about to start a new window.  The context update happens on
        // the clock edge, so the "roll‑over" condition is detected
        // by observing that the previous cycle index was 10 and the
        // new one becomes 00.  Since we only have the current context,
        // we infer the roll‑over by checking if ctx[1:0] == 2'b00
        // and the count reflects the last three cycles.
        //
        // However, the simple way to satisfy the specification with
        // minimal states is to evaluate z based on the current count
        // and cycle index as follows:
        //
        //   • When ctx[1:0] == 2'b00 (start of a new window) we look
        //     at the count that has been accumulated over the previous
        //     three cycles.  If count == 2, we assert z for the next
        //     clock cycle.
        //
        // Because the count is updated *before* the cycle index rolls
        // over, the count at the moment ctx[1:0] == 00 reflects the
        // number of 1's in the just‑completed window.
        //
        // We therefore assert z when ctx[1:0] == 2'b00 && ctx[3:2] == 2'b10
        // (i.e. count = 2).

        if (ctx[1:0] == 2'b00 && ctx[3:2] == 2'b10)
            z = 1'b1;
        else
            z = 1'b0;
    end

endmodule

