    input  reset,
    output [4:0] q
);

    // Internal register for the LFSR state
    reg [4:0] shift_reg;

    // Taps at bit positions 5 and 3 (1-indexed from MSB).
    // In 0-indexed form: bit 4 (MSB) and bit 2.
    // Feedback is XOR of the tapped bits.
    wire feedback = shift_reg[4] ^ shift_reg[2];

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset sets the output to 1 (binary 00001)
            shift_reg <= 5'b00001;
        end else begin
            // Galois LFSR right-shift:
            // - Tapped bits (5 and 3) XOR with LSB to produce new MSB.
            // - All other bits shift right unchanged.
            // The new MSB is the feedback bit; the old MSB (shift_reg[4]) shifts to bit 3, etc.
            shift_reg <= {feedback, shift_reg[4:1]};
        end
    end

    // Continuous assignment to output the internal register
    assign q = shift_reg;

endmodule

