module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // State encoding: 4 bits are used to give each state a unique value
    typedef enum logic [3:0] {
        IDLE      = 4'b0000,
        START     = 4'b0001,
        DATA0     = 4'b0010,
        DATA1     = 4'b0011,
        DATA2     = 4'b0100,
        DATA3     = 4'b0101,
        DATA4     = 4'b0110,
        DATA5     = 4'b0111,
        DATA6     = 4'b1000,
        DATA7     = 4'b1001,
        STOP      = 4'b1010
    } state_t;

    // Registers
    state_t   state, next_state;
    logic [7:0] shift_reg;  // Holds the 8 received data bits
    logic [3:0] bit_cnt;    // Counter for bit position (0-7)
    logic       stop_check; // Flag to indicate we are checking the stop bit

    // Output assignment
    // 'done' pulses high for one clock cycle when a complete byte is received correctly
    // (Stop bit sampled as 1 while in the STOP state).
    assign done = (state == STOP) & in;

    // State register (positive edge-triggered, active-high synchronous reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 8'b0;
            bit_cnt   <= 4'b0;
        end else begin
            state     <= next_state;
            // Shift register only shifts during data collection
            if (state >= START && state <= DATA7)
                shift_reg <= {in, shift_reg[7:1]};
            else
                shift_reg <= shift_reg;
            // Bit counter logic
            if (state == START)
                bit_cnt <= 4'b1; // Start bit counted as bit 0, next is bit 1
            else if (state >= DATA0 && state <= DATA7)
                bit_cnt <= bit_cnt + 1'b1;
            else if (state == STOP)
                bit_cnt <= 4'b0;
            else
                bit_cnt <= 4'b0;
        end
    end

    // Next-state combinational logic
    always_comb begin
        next_state = state; // Default: stay in current state

        case (state)
            IDLE: begin
                if (~in)        // Start bit detected (falling edge)
                    next_state = START;
                else
                    next_state = IDLE;
            end

            START: begin
                // Wait one clock to verify start bit is still 0 (optional robustness)
                // Then move to data bit 0
                next_state = DATA0;
            end

            DATA0, DATA1, DATA2, DATA3, DATA4, DATA5, DATA6, DATA7: begin
                // Collect 8 data bits (LSB first)
                if (bit_cnt == 4'd7) begin // After data bit 7
                    next_state = STOP;
                end else begin
                    next_state = state; // Stay in data state, counter will increment next cycle
                end
            end

            STOP: begin
                if (in)        // Stop bit must be 1
                    next_state = IDLE;
                else
                    next_state = STOP; // Keep waiting for stop bit
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

