module TopModule (
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);

    // State encoding: 4 bits are needed to have 8 unique values (0-7) plus extra states
    typedef enum logic [3:0] {
        IDLE      = 4'b0000,
        START     = 4'b0001,
        DATA0     = 4'b0010,
        DATA1     = 4'b0011,
        DATA2     = 4'b0100,
        DATA3     = 4'b0101,
        DATA4     = 4'b0110,
        DATA5     = 4'b0111,
        DATA6     = 4'b1000,
        DATA7     = 4'b1001,
        STOP      = 4'b1010,
        VALID     = 4'b1011
    } state_t;

    state_t state, next_state;
    reg [7:0] data_reg;
    reg done_reg;

    // State register update (positive edge, synchronous reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data_reg <= 8'b0;
            done_reg <= 1'b0;
        end else begin
            state <= next_state;
            data_reg <= data_reg;
            done_reg <= done_reg;
        end
    end

    // Next-state and output combinational logic
    always_comb begin
        // Default assignments
        next_state = state;
        done_reg   = 1'b0;

        case (state)
            IDLE: begin
                if (~in) begin // start bit detected (active low)
                    next_state = START;
                end else begin
                    next_state = IDLE;
                end
            end

            START: begin
                // Wait one clock cycle to sample the start bit (optional, but good practice)
                // Then sample data bits. We assume the start bit is already valid.
                next_state = DATA0;
            end

            DATA0: begin
                // Sample bit 0 (LSB)
                data_reg[0] = in;
                next_state = DATA1;
            end

            DATA1: begin
                data_reg[1] = in;
                next_state = DATA2;
            end

            DATA2: begin
                data_reg[2] = in;
                next_state = DATA3;
            end

            DATA3: begin
                data_reg[3] = in;
                next_state = DATA4;
            end

            DATA4: begin
                data_reg[4] = in;
                next_state = DATA5;
            end

            DATA5: begin
                data_reg[5] = in;
                next_state = DATA6;
            end

            DATA6: begin
                data_reg[6] = in;
                next_state = DATA7;
            end

            DATA7: begin
                data_reg[7] = in;
                // After MSB, check stop bit in the next cycle
                next_state = STOP;
            end

            STOP: begin
                // Verify stop bit is 1
                if (in) begin
                    next_state = VALID;
                    done_reg   = 1'b1; // assert done
                end else begin
                    // Stop bit missing: wait for next start bit
                    // Since we are sampling 'in', if it's 0, it's a start bit.
                    // If it's 1, we stay in STOP until it becomes 0.
                    next_state = STOP;
                    done_reg   = 1'b0;
                end
            end

            VALID: begin
                // out_byte is valid, done is high for one cycle
                // Immediately go back to IDLE to wait for next byte
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output assignments
    assign out_byte = data_reg;
    assign done     = done_reg;

endmodule

