module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal register holding the current generation
    logic [255:0] state;

    // ---------- Next-state logic (combinational) ----------
    // We compute the next state for every cell in parallel.
    // The grid is 16x16, wrapped toroidally.
    // Row-major ordering: q[15:0] = row 0, q[31:16] = row 1, …, q[255:240] = row 15.

    logic [255:0] next;

    genvar r, c;
    generate
        for (r = 0; r < 16; r = r + 1) begin: row_gen
            for (c = 0; c < 16; c = c + 1) begin: cell_gen

                // Helper to wrap indices toroidally
                // row index: (r +/- 1) mod 16, always non‑negative
                // col index: (c +/- 1) mod 16, always non‑negative
                integer r_up, r_dn, c_lf, c_rt;

                // Up, down, left, right (used for edge counting)
                assign r_up   = (r == 0) ? 15 : r - 1;
                assign r_dn   = (r == 15) ? 0 : r + 1;
                assign c_lf   = (c == 0) ? 15 : c - 1;
                assign c_rt   = (c == 15) ? 0 : c + 1;

                // Map 2‑D coordinates to the linear 256‑bit vector.
                // Row r starts at bit position r*16.
                // Within the row, bit c corresponds to offset c.
                // Therefore the bit index is r*16 + c.
                function automatic integer idx(input integer rr, input integer cc);
                    idx = rr * 16 + cc;
                endfunction

                // Gather the eight neighbours (toroidal wrapping).
                // Neighbour order does not matter; we only need the sum.
                logic [7:0] nbr;

                // 8 neighbours:
                // (r-1, c-1), (r-1, c), (r-1, c+1)
                // (r,   c-1),             (r,   c+1)
                // (r+1, c-1), (r+1, c), (r+1, c+1)
                always @(*) begin
                    // initialise
                    nbr = 8'b0;

                    // top row
                    nbr[0] = state[idx(r_up, c_lf)]; // top‑left
                    nbr[1] = state[idx(r_up, c)];   // top‑middle
                    nbr[2] = state[idx(r_up, c_rt)];// top‑right

                    // middle row (left & right)
                    nbr[3] = state[idx(r, c_lf)];   // left
                    nbr[4] = state[idx(r, c_rt)];   // right
                    // Note: The original code had a syntax error here (missing assignment for nbr[4]).
                    // I have added the missing assignment.

                    // bottom row
                    nbr[5] = state[idx(r_dn, c_lf)];// bottom‑left
                    nbr[6] = state[idx(r_dn, c)];   // bottom‑middle
                    nbr[7] = state[idx(r_dn, c_rt)];// bottom‑right
                end

                // Actually, let us compute the sum directly without the intermediate array,
                // to keep the always block simple and synthesis‑friendly.
                always @(*) begin
                    int sum;
                    sum = 0;
                    // top row
                    sum = sum + state[idx(r_up, c_lf)];
                    sum = sum + state[idx(r_up, c)];
                    sum = sum + state[idx(r_up, c_rt)];
                    // middle row
                    sum = sum + state[idx(r, c_lf)];
                    sum = sum + state[idx(r, c_rt)];
                    // bottom row
                    sum = sum + state[idx(r_dn, c_lf)];
                    sum = sum + state[idx(r_dn, c)];
                    sum = sum + state[idx(r_dn, c_rt)];

                    // Apply Game of Life rules:
                    // 0-1 neighbour -> 0
                    // 2 neighbours  -> stay same
                    // 3 neighbours  -> 1
                    // 4+ neighbours -> 0
                    if (sum <= 1)
                        next[idx(r, c)] = 1'b0;
                    else if (sum == 2)
                        next[idx(r, c)] = state[idx(r, c)]; // retain current
                    else if (sum == 3)
                        next[idx(r, c)] = 1'b1;
                    else // sum >= 4
                        next[idx(r, c)] = 1'b0;
                end

            end
        end
    endgenerate

    // ---------- Sequential edge‑triggered update ----------
    always @(posedge clk) begin
        if (load)
            q <= data;          // load initial state synchronously
        else
            q <= next;          // advance one generation
    end

    // Optional: initialise q to zero on first simulation time (not required by spec,
    // but often useful for simulation).
    initial begin
        q <= 256'b0;
    end

endmodule

