    input        w,   // control input
    output       Y1   // output assignment
);

    // Y1 is directly assigned to y[1]
    assign Y1 = y[1];

    // The next-state logic for y[1] is derived from the FSM transition table.
    // The state encoding is: A=000, B=001, C=010, D=011, E=100, F=101.
    // y[1] is the middle bit of the state code.
    // The next value of y[1] depends only on the current state and w,
    // and is independent of y[0] and y[2] for the given transitions.
    //
    // Derivation:
    //   A(000) --0/1--> A(000): y[1] next = 0
    //   B(001) --0--> C(010): y[1] next = 1  (w=0)
    //   B(001) --1--> D(011): y[1] next = 1  (w=1)  -> always 1 from B
    //   C(010) --0--> E(100): y[1] next = 0  (w=0)
    //   C(010) --1--> D(011): y[1] next = 1  (w=1)  -> y[1] next = w
    //   D(011) --0--> F(101): y[1] next = 0  (w=0)
    //   D(011) --1--> A(000): y[1] next = 0  (w=1)  -> y[1] next = ~w
    //   E(100) --0--> E(100): y[1] next = 0  (w=0)
    //   E(100) --1--> D(011): y[1] next = 1  (w=1)  -> y[1] next = w
    //   F(101) --0--> C(010): y[1] next = 1  (w=0)  -> y[1] next = ~w
    //   F(101) --1--> D(011): y[1] next = 1  (w=1)  -> always 1 from F
    //
    // Truth table for y[1] next:
    //   current state \ w | 0 | 1
    //   A(000)            | 0 | 0  -> 0
    //   B(001)            | 1 | 1  -> 1
    //   C(010)            | 0 | 1  -> w
    //   D(011)            | 0 | 0  -> ~w
    //   E(100)            | 0 | 1  -> w
    //   F(101)            | 1 | 1  -> 1
    //
