module TopModule (
    input  clk,
    input  a,
    input  b,
    output q,
    output state
);

    reg q_reg;
    reg state_reg;

    always @(posedge clk) begin
        // Deterministic state transition based on inputs
        if (a == 1'b0 && b == 1'b0) begin
            state_reg <= 1'b0;
        end else if (a == 1'b0 && b == 1'b1) begin
            state_reg <= 1'b1;
        end else if (a == 1'b1 && b == 1'b0) begin
            state_reg <= 1'b0;
        end else if (a == 1'b1 && b == 1'b1) begin
            state_reg <= ~state_reg;
        end
        // Output q follows the flip-flop state
        q_reg <= state_reg;
    end

    assign q = q_reg;
    assign state = state_reg;

endmodule

