module TopModule (
    input  [3:0] in,
    output [1:0] pos
);

    // Priority encoder logic:
    // Bit 3 has the highest priority, bit 0 the lowest.
    // If multiple bits are high, the position of the most significant high bit is returned.
    // When all bits are zero, pos outputs 2'b00.

    always @(*) begin
        case (in)
            4'b1xxx: pos = 2'b11; // bit[3] is high
            4'b01xx: pos = 2'b10; // bit[2] is high (and bit[3] is low)
            4'b001x: pos = 2'b01; // bit[1] is high (and bits[3:2] are low)
            4'b0001: pos = 2'b00; // bit[0] is high (and bits[3:1] are low)
            default: pos = 2'b00; // all bits are low
        endcase
    end

endmodule

