module TopModule (
    input  clk,
    input  in,
    output out
);

    // Internal signal for the D flip-flop input
    wire d_input;

    // Internal register to hold the flip-flop state
    reg q;

    // XOR gate: inputs are 'in' and the flip-flop output 'out'
    assign d_input = in ^ out;

    // Positive edge-triggered D flip-flop with no reset
    always @(posedge clk) begin
        q <= d_input;
    end

    // Continuous assignment to drive the output port 'out' from the register
    assign out = q;

endmodule

