Prob151_review2015_fsm.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

// State encoding
typedef enum logic [2:0] {
    IDLE       = 3'b000,  // Searching for start pattern 1101
    SHIFTING   = 3'b001,  // Shift in 4 bits to determine duration
    COUNTING   = 3'b010,  // Waiting for counters to finish
    DONE_STATE = 3'b011   // Timer timed out, waiting for ack
} state_t;

state_t state, next_state;

// Shift register to detect the pattern 1101
// We keep the last 4 bits of the serial stream
logic [3:0] shift_reg;

// Detect rising edge of the pattern 1101
// Pattern detected when shift_reg == 4'b1101
always_ff @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else begin
        // Shift in new data bit
        shift_reg <= {shift_reg[2:0], data};
    end
end

// State transition logic (Moore machine)
always_ff @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Internal counter to ensure shift_ena is asserted for exactly 4 clock cycles
logic [1:0] cycle_cnt;

// Next-state and output logic (combinational)
always_comb begin
    // Default assignments: keep outputs unchanged unless transitioning
    next_state = state;
    shift_ena  = 1'b0;
    counting   = 1'b0;
    done       = 1'b0;

    case (state)
        IDLE: begin
            // Look for the start pattern 1101
            if (shift_reg == 4'b1101) begin
                next_state = SHIFTING;
                cycle_cnt    = 2'b00; // Reset counter when entering SHIFTING
            end else begin
                next_state = IDLE;
            end
        end

        SHIFTING: begin
            // Assert shift_ena for exactly 4 clock cycles
            shift_ena = 1'b1;

            // Internal counter logic to stay in SHIFTING for 4 cycles
            // cycle_cnt counts from 0 to 3 (4 states)
            if (cycle_cnt == 2'b11) begin
                // After 4 cycles, transition to COUNTING
                next_state = COUNTING;
            end else begin
                // Increment counter, staying in SHIFTING
                next_state = SHIFTING;
                // Note: cycle_cnt update happens in the sequential block below
            end
        end

        COUNTING: begin
            counting = 1'b1;
            if (done_counting) begin
                next_state = DONE_STATE;
            end else begin
                next_state = COUNTING;
            end
        end

        DONE_STATE: begin
            done = 1'b1;
            if (ack) begin
                next_state = IDLE;
            end else begin
                next_state = DONE_STATE;
            end
        end

        default: next_state = IDLE;
    endcase
end

// Sequential block for internal counter and state update
always_ff @(posedge clk) begin
    if (reset) begin
        state       <= IDLE;
        cycle_cnt   <= 2'b00;
    end else begin
        state       <= next_state;
        // Update cycle counter only in SHIFTING state
        if (state == SHIFTING) begin
            if (cycle_cnt == 2'b11) begin
                cycle_cnt <= 2'b00; // Reset after reaching 3
            end else begin
                cycle_cnt <= cycle_cnt + 1'b1;
            end
        end else begin
            cycle_cnt <= 2'b00; // Reset counter when leaving SHIFTING
        end
    end
end

endmodule

