module TopModule (
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // 7-bit global branch history register
    reg [6:0] ghr;
    // 128-entry PHT (7-bit index, 2-bit counters)
    reg [1:0] pht [0:127];

    // Internal signals for prediction
    wire [6:0] idx;
    wire [1:0] pht_val;
    wire taken_pred;

    // Assign index: XOR of PC and GHR[6:0]
    assign idx = predict_pc ^ ghr;

    // Read PHT value at predicted index
    assign pht_val = pht[idx];

    // Predict taken if counter >= 2
    assign taken_pred = (pht_val >= 2'b10);
    assign predict_taken = taken_pred;
    assign predict_history = ghr;

    // Training logic: update PHT and GHR
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // Initialize PHT counters to weakly taken (2'b10)
            integer i;
            for (i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b10;
        end else begin
            // Default: GHR updates on prediction
            // If training valid, training takes precedence for GHR update
            if (train_valid) begin
                // Update GHR to train state after mispredict
                if (train_mispredicted)
                    ghr <= train_history;
                else
                    ghr <= {ghr[5:0], train_taken};
            end else begin
                // Prediction updates GHR
                ghr <= {ghr[5:0], taken_pred};
            end

            // Update PHT
            if (train_valid) begin
                // Training updates PHT immediately (at next clock edge)
                if (train_mispredicted) begin
                    // Decrement or increment based on actual outcome
                    if (train_taken)
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] + 1'b1;
                    else
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] - 1'b1;
                end else begin
                    // Train based on actual outcome
                    if (train_taken)
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] + 1'b1;
                    else
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] - 1'b1;
                end
                // Clamp counters
                if (pht[train_pc ^ train_history] > 3) pht[train_pc ^ train_history] <= 3;
                if (pht[train_pc ^ train_history] < 0) pht[train_pc ^ train_history] <= 0;
            end
            // If only prediction, PHT not updated here (updates on next prediction cycle if needed, but spec implies training updates PHT)
        end
    end

endmodule

